    properties (GetAccess = public, SetAccess = protected)
        b;
        te;
        Delta;
        delta;
        g;
        Scsf;

        % tissue properties
        R2c     = 1/126.97e-3;  % axonal T2 constant term [1/s] 
        rho2    = 1.16*2;       % axonal surface to volume ratio [um/s]
        Dcsf    = 3;            % diffusivity in CSF [um2/ms]
        D0      = 1.7;          % intrinsic diffusivity in tissue [um2/ms]
        Da      = 1.7;          % axonal longitudinal diffusivity [um2/ms]
        DeL     = 1.7;          % extracellular longitudinal diffusivity [um2/ms]
        R2csf   = 0.5;          % R2(=1/T2) of CSF [1/s]
        model   = 'wide';
        % Radius distribution family for the gamma/lognormal/inverse-
        % Gaussian/log-logistic effective-radius conversion (see FWD/
        % moments_to_effective_radii) -- 'gamma'|'lognormal'|
        % 'inversegaussian'|'loglogistic'. Set via the constructor's 7th
        % argument. Default 'gamma' (matches gpuMEAxCaliberSMT_gammaDist.m).
        distribution = 'gamma';
    end
    
    properties (GetAccess = private, SetAccess = private)
       
    end
    
    methods

        % constructuor
        function this = gpuMEAxCaliberSMT_radiusDist(b, delta, Delta, te, tissueProperties, model, distribution)
        % Estimation of neurite fraction and intrinsic diffusivity using SMT with th eoption of performing compartmental T2 mapping
        % smt = gpuSMT(b, te)
        %       output:
        %           - smt: object of a fitting class
        %
        %       input:
        %           - b:        b-value                 [ms/um2]
        %           - delta:    gradient duration       [ms]
        %           - Delta:    gradient seperation     [ms]
        %           - te:       echo time               [s] (if Nt>1)
        %           - tissueProperties
        %               .D0:    Intrinsic diffusivity of axons [um2/ms] (default: 1.7)
        %               .Da:    Axonal longitudinal diffusivity [um2/ms] (default: 1.7)
        %               .DeL:   Extracellular longitudinal diffusivity [um2/ms] (default: 1.7)
        %               .Dcsf:  CSF diffusivity [um2/ms] (default: 3)
        %               .R2csf: R2(=1/T2) of CSF [1/s] (default: 0.5)
        %               .R2c:   Intrinsic axonal R2 [1/s] (default:1/126.97e-3)
        %               .rho2:  coeffient of 1/r dependence [um/s] (default:1.16*2)
        %           -model: 'narrow' or 'wide' pulse
        %
        %  Authors: 
        %  Kwok-Shing Chan (kchan2@mgh.harvard.edu)
        %
            
            % sequence parameters
            % diffusion
            % Deduplicate raw per-direction (b,delta,Delta,te) into unique
            % shells (keeping b=0 volumes distinct per-TE) -- ported from
            % gpuMEAxCaliberSMT.m's constructor. Without this, this.b
            % ends up the same length as a raw multi-direction DWI's 4th
            % dimension, which makes prepare_dwi_data's spherical-mean-
            % computation check (size(dwi,4) > numel(this.b)) false and
            % SKIPS spherical mean computation entirely -- the bug this
            % fixes.
            [b,delta,Delta,te] = DWIutility.unique_shell_keepb0(b,delta,Delta,te,false);

            b           = max(b,1e-10); % make sure b is not zero
            this.b      = (single( b(:)) );
            this.delta  = (single( delta(:))) ;
            this.Delta  = (single( Delta(:))) ;
            this.g      = (single( sqrt(b(:)./delta(:).^2./(Delta(:)-delta(:)/3)))) ;
            % relaxation
            if isempty(te)
                this.te = zeros(size(this.b));    % no input te assume single TE
            else
                if isscalar(unique(te))
                    this.te = zeros(size(this.b));    % only 1 TE then set TE to 0
                else
                    this.te = single(te(:));    % same length as b or scalar (if Nt==1)
                end
            end

            % user defined
            % diffusion
            % (bug fix: these previously referenced bare undefined
            % variables D0/Da/DeL/Dcsf/R2csf/R2c/rho2 instead of
            % tissueProperties.<field> -- harmless only because every
            % caller so far has passed an empty tissueProperties struct)
            if isfield(tissueProperties,'D0');      this.D0     = (single( tissueProperties.D0 ));       end
            if isfield(tissueProperties,'Da');      this.Da     = (single( tissueProperties.Da ));       end
            if isfield(tissueProperties,'DeL');     this.DeL    = (single( tissueProperties.DeL ));      end
            if isfield(tissueProperties,'Dcsf');    this.Dcsf   = (single( tissueProperties.Dcsf ));     end
            % relaxation
            if isfield(tissueProperties,'R2csf');   this.R2csf  = (single( tissueProperties.R2csf ));    end
            if isfield(tissueProperties,'R2c');     this.R2c    = (single( tissueProperties.R2c ));      end
            if isfield(tissueProperties,'rho2');    this.rho2   = (single( tissueProperties.rho2 ));     end

            if ~isempty(model); this.model  = model;                        end

            % radius distribution family -- 'gamma'|'lognormal'|
            % 'inversegaussian'|'loglogistic' (default 'gamma', set in
            % the property block, if this arg is omitted/empty)
            if nargin >= 7 && ~isempty(distribution)
                this.distribution = lower(distribution);
            end
            % log-logistic's diffusion effective-radius formula only
            % exists for r_cov < ~0.3204 (the underlying shape parameter
            % beta must stay >6 for the 6th raw moment to be finite --
            % see moments_to_effective_radii/loglogistic_cGrid). Tighten
            % r_cov's upper bound accordingly -- the class-default ub
            % (see modelParams/ub above) is unreachable/unsafe for this
            % family specifically.
            if strcmpi(this.distribution,'loglogistic')
                this.ub(ismember(this.modelParams,'r_cov')) = single(0.30);
            end

            this.Scsf   = ( single(exp(-this.b*this.Dcsf).*exp(-this.te*this.R2csf)) );

        end

        % update properties according to lmax
        function this = updateProperty(this, fitting)

            % only 1 TE, reduce the model to standard AxCaliberSMT
            if unique(this.te) == 0
                for kpar = {'R2a','R2e','k2a'}
                    idx = find(ismember(this.modelParams,kpar));
                    this.modelParams(idx)   = [];
                    this.lb(idx)            = [];
                    this.ub(idx)            = [];
                    this.startPoint(idx)    = [];
                end
            end

            % whether fitting CSF compartment or not
            if ~fitting.isFitCSF
                idx = find(ismember(this.modelParams,'fcsf'));
                this.modelParams(idx)       = [];
                this.lb(idx)                = [];
                this.ub(idx)                = [];
                this.startPoint(idx)        = [];
            end

            % whether fitting CSF compartment or not
            if ~fitting.isFitR2a
                idx = find(ismember(this.modelParams,'R2a'));
                this.modelParams(idx)       = [];
                this.lb(idx)                = [];
                this.ub(idx)                = [];
                this.startPoint(idx)        = [];
            end
            % whether fitting CSF compartment or not
            if ~fitting.isFitk2a
                idx = find(ismember(this.modelParams,'k2a'));
                this.modelParams(idx)       = [];
                this.lb(idx)                = [];
                this.ub(idx)                = [];
                this.startPoint(idx)        = [];
            end

        end
    
        % display some info about the input data and model parameters
        function display_data_model_info(this)

            disp('==================================================');
            disp('Multi-echo (ME) AxCaliberSMT with askadam.m solver');
            disp('==================================================');
            fprintf('Radius distribution family     : %s\n', this.distribution);

            disp('----------------')
            disp('Data Information');
            disp('----------------')
            fprintf('b-shells (ms/um2)              : [%s] \n',num2str(this.b.',' %.2f'));
            fprintf('Gradient pulse duration (ms)   : [%s] \n',num2str(this.delta.',' %i'));
            fprintf('Diffusion time (ms)            : [%s] \n\n',num2str(this.Delta.',' %i'));
            if ~unique(this.te) == 0
                fprintf('TE (ms)                        : [%s] \n',num2str(this.te.'*1e3,' %.2f'));
            end
            disp('----------------')

            disp('----------------')
            disp('Fixed parameters');
            disp('----------------')
            disp(['Diffusivity intra-cellular intrinsic (um2/ms): ' num2str(this.D0,'%.2f')]);
            disp(['Diffusivity intra-cellular axial (um2/ms)    : ' num2str(this.Da,'%.2f')]);
            disp(['Diffusivity extra-cellular axial (um2/ms)    : ' num2str(this.DeL,'%.2f')]);
            disp(['Diffusivity CSF (um2/ms)                     : ' num2str(this.Dcsf,'%.2f')]);
            if ~unique(this.te) == 0
                disp(['Intrinsic intra-axonal T2 (ms)               : ' num2str(1/this.R2c*1e3,'%.2f')]);
                disp(['Surface-to-volume ratio constant (ms)        : ' num2str(this.rho2,'%.2f')]);
            end
            disp('----------------')

        end

        %% higher-level data fitting functions

        % This is a wrapper of the 'fit' function.
        % The main purpose of this function is to handle memory issue and ensure the input data is correct for 'fit'
        function  [out] = estimate(this, dwi, mask, fitting, extraData, pars0)
        % Input data are expected in multi-dimensional image
        % 
        % Input
        % -----------
        % dwi       : 4D DWI, [x,y,z,dwi]
        % mask      : 3D signal mask, [x,y,z]
        % extradata : Optional additional data
        %   .bval       : 1D bval in ms/um2, [1,dwi]                (Optional, only needed if dwi is full acquisition)
        %   .bvec       : 2D b-table, [3,dwi]                       (Optional, only needed if dwi is full acquisition)
        %   .ldelta     : 1D gradient pulse duration in ms, [1,dwi] (Optional, only needed if dwi is full acquisition)
        %   .BDELTA     : 1D diffusion time in ms, [1,dwi]          (Optional, only needed if dwi is full acquisition)
        % fitting   : fitting algorithm parameters (see fit function)
        % 
        % Output
        % -----------
        % out       : output structure contains all parameter estimation results
        % 
            % if no pars input at all (not even empty) then use prior
            if nargin < 6; pars0        = []; end
            if nargin < 5; extraData    = []; end

            % display basic info
            this.display_data_model_info;

            % get all fitting algorithm parameters
            fitting = this.check_set_default(fitting);

            %%%%%%%%%%%%%%%% Step 1: Validate all input data %%%%%%%%%%%%%%%%
            % compute rotationally invariant signal if needed
            lmax        = 0;    % only spherical mean
            [dwi,mask,scaleFactor] = this.prepare_dwi_data(dwi,mask,extraData,lmax,fitting);

            % convert datatype to single or logical
            % (NaN/Inf removal is now handled inside prepare_dwi_data's QC
            % pipeline -- no separate utils.remove_img_naninf call needed)
            dwi     = single(dwi);
            mask    = mask >0;
            if ~isempty(pars0); for km = 1:numel(this.modelParams); pars0.(this.modelParams{km}) = single(pars0.(this.modelParams{km})); end; end

            %%%%%%%%%%%%%%%% End Step 1 %%%%%%%%%%%%%%%%

            %%%%%%%%%%%%%%%% Step 2: Memory management %%%%%%%%%%%%%%%%
            % --- [Experimental] estimate memory usage using a small batch of data size ---
            % this method tends to be more conservative than the actual memory ussage
            [seg,NSegment] = utils.find_optimal_segment_3D(this, dwi, mask, fitting, pars0);

            % parameter estimation
            out = [];
            for kseg = 1:NSegment

                if NSegment > 1
                    fprintf('Running #Segment = %d/%d \n',kseg,NSegment);
                    disp   ('------------------------')
                end

                % divide the data; fitRange includes halo slices (if any), ownedRange
                % is what this segment is responsible for writing back
                fitRange                        = seg(kseg).fit;
                ownedRange                      = seg(kseg).owned;
                [dwiSeg, maskSeg, pars0Seg]     = this.slice_segment(dwi, mask, fitRange, pars0);

                % run fitting
                [outSeg] = this.fit(dwiSeg,maskSeg,fitting,pars0Seg);

                % discard halo slices from this segment's output before restoring,
                % so segment boundaries never keep voxels from a neighbour's
                % independently-converged fit (no-op when seg(kseg).fit == .owned)
                outSeg = utils.crop_segment_output(outSeg, seg(kseg));

                % restore 'out' structure from segment
                out = utils.restore_segment_structure(out,outSeg,ownedRange,kseg);

            end
            out.mask        = mask;
            out.scaleFactor = scaleFactor;   % global reference-signal scalar from prepare_dwi_data
            %%%%%%%%%%%%%%%% End Step 2 %%%%%%%%%%%%%%%%

            % save the estimation results if the output filename is provided
            askadam.save_askadam_output(fitting.outputFilename,out)

        end

        % Data fitting function
        % This is a wapper of the askadam class 'fit' function
        function [out] = fit(this,dwi,mask,fitting, pars0)
        %
        % Input
        % -----------
        % dwi       : S0 normalised 4D dwi images, [x,y,slice,diffusion], 4th dimension corresponding to [Sl0_b1,Sl0_b2 etc.]; the order of bval must match the order in the constructor 
        % mask      : 3D signal mask, [x,y,slice]
        % fitting   : fitting algorithm parameters
        %   .Nepoch             : no. of maximum iterations, default = 4000
        %   .initialLearnRate   : initial gradient step size, defaulr = 0.01
        %   .decayRate          : decay rate of gradient step size; learningRate = initialLearnRate / (1+decayRate*epoch), default = 0.0005
        %   .convergenceValue   : convergence tolerance, based on the slope of last 'convergenceWindow' data points on loss, default = 1e-8
        %   .convergenceWindow  : number of data points to check convergence, default = 20
        %   .tol                : stop criteria on metric value, default = 1e-3
        %   .lambda             : regularisation parameter, default = 0 (no regularisation)
        %   .TVmode             : mode for TV regulariation, '2D'|'3D', default = '2D'
        %   .regmap             : parameter map used for regularisation, 'fa'|'ra'|'Da'|'De', default = 'fa'
        %   .lmax               : Order of rotational invariant, 0|2, default = 0
        %   .lossFunction       : loss for data fidelity term, 'L1'|'L2'|'MSE', default = 'L1'
        %   .display            : online display the fitting process on figure, true|false, defualt = false
        % pars0     : structure variable of starting points of fitting (optional)
        % 
        % Output
        % -----------
        % out       : output structure
        %   .final      : final results
        %   .min        : results with the minimum loss metric across all iterations
        %       .loss       : loss metric      
        %
        % Kwok-Shing Chan @ MGH
        % kchan2@mgh.harvard.edu
        % Date created: 1 Oct 2025
        % Date modified:
        %
            
            % check GPU
            gpool = gpuDevice;
            
            % check image size
            dims = size(dwi,1:3);

            %%%%%%%%%%%%%%%%%%%% Step 1. Validate and parse input %%%%%%%%%%%%%%%%%%%%
            if nargin < 3 || isempty(mask); mask = ones(dims,'logical'); end % if no mask input then fit everthing
            if nargin < 4; fitting = struct(); end
            % set initial tarting points
            if nargin < 5; pars0 = []; % no initial starting points
            else
                if ~isempty(pars0); for km = 1:numel(this.modelParams); pars0.(this.modelParams{km}) = single(pars0.(this.modelParams{km})); end; end
            end

            % get all fitting algorithm parameters 
            fitting                 = this.check_set_default(fitting);
            % determine fitting parameters
            this                    = this.updateProperty(fitting);
            fitting.modelParams     = this.modelParams;
            % set fitting boundary if no input from user
            if isempty( fitting.ub); fitting.ub = this.ub(1:numel(fitting.modelParams)); end
            if isempty( fitting.lb); fitting.lb = this.lb(1:numel(fitting.modelParams)); end

            %%%%%%%%%%%%%%%%%%%% End 1 %%%%%%%%%%%%%%%%%%%%

            %%%%%%%%%%%%%%%%%%%% 2. Setting up all necessary data, run askadam and get all output %%%%%%%%%%%%%%%%%%%%
            % 2.1 setup fitting weights
            lmax    = 0;
            w       = this.compute_optimisation_weights(mask,fitting.lossFunction,lmax); % This is a customised funtion

            % 2.2 estimate prior if needed
            if isempty(pars0);  pars0 = this.determine_x0(dwi,mask,fitting); end

            % 2.3 askAdam optimisation main
            out         = this.run_askadam(dwi, mask, w, pars0, fitting);

            %%%%%%%%%%%%%%%%%%%% End 2 %%%%%%%%%%%%%%%%%%%%

            disp('The estimation is completed.');

            % clear GPU
            reset(gpool)

        end

        % Thin wrapper of askadam().optimisation -- kept as its own method
        % (matching gpuMEAxCaliberSMT.m's run_askadam) so fit() dispatches
        % through a named solver entry point rather than constructing
        % askadam() inline. No lambdaR2aPrior/custom-regularisation hook
        % here (out of scope for this class -- see gpuMEAxCaliberSMT.m's
        % run_askadam/reg_R2aPrior if that's ever needed), and no 'solver'
        % argument passed to FWD (this class's FWD has no mcmc-specific
        % arrayfun branch, unlike gpuMEAxCaliberSMT.m's).
        function out = run_askadam(this, data, mask, w, pars0, fitting)
            out = askadam().optimisation(data, mask, w, pars0, fitting, @this.FWD);
        end

        function [dataSeg, maskSeg, pars0Seg] = slice_segment(this, data, mask, slice, pars0)

            dataSeg     = data(:,:,slice,:,:,:,:,:,:);
            maskSeg     = mask(:,:,slice);
            if ~isempty(pars0)
                for km = 1:numel(this.modelParams)
                    pars0Seg.(this.modelParams{km}) = pars0.(this.modelParams{km})(:,:,slice);
                end
            else
                pars0Seg = [];
            end

        end

        %% Data preparation

        % compute rotationally invariant DWI signal if necessary, then
        % run the QC/scale-normalisation pipeline (ported from
        % gpuMEAxCaliberSMT.m's prepare_dwi_data) -- global-scalar
        % reference-signal normalisation (scaleFactor), then exclusion of
        % biophysically-impossible/background/incoherent/NaN-Inf voxels
        % from mask. isFitS0 is NOT supported by this class (out of
        % scope) -- always treated as false, i.e. the per-voxel
        % dwi./dwi(:,:,:,1) normalisation always runs.
        function [dwi,mask,scaleFactor] = prepare_dwi_data(this,dwi,mask,extradata,lmax,fitting)

            % full DWI data then compute rotaionally invariant signal
            if size(dwi,4)/(lmax/2+1) > numel(this.b)
                % compute spherical mean signal
                fprintf('Computing rotationally invariant signal...')

                % if the inout little delta is one value then create a vector
                if isscalar(extradata.ldelta)
                    extradata.ldelta = ones(size(extradata.bval)) * extradata.ldelta;
                end
                if ~isfield(extradata,'te')
                    extradata.te = zeros(size(extradata.bval));
                elseif isscalar(extradata.te)
                    extradata.te = ones(size(extradata.bval)) * extradata.te;
                end
                DWIutilityObj   = DWIutility();
                [dwi]           = DWIutilityObj.get_Sl_all_no_normalise(dwi,extradata.bval,extradata.bvec,extradata.ldelta,extradata.BDELTA,extradata.te,lmax);

                fprintf('done.\n');

            elseif size(dwi,4) < numel(this.b)
                error('There are more b-shells in the class object than available in the input data. Please check your input data.');
            end

            % sort the order of the signal based on TE, Delta, delta and b
            % (this class -- unlike gpuMEAxCaliberSMT.m -- does this sort
            % here rather than once in the constructor, so this.b/te/
            % Delta/delta and dwi's 4th dimension stay in the same order
            % expected by the rest of this method and by FWD)
            acqTable = [this.b, this.te, this.Delta, this.delta, (1:numel(this.te)).'];

            % Sort rows first by TE, Delta, delta and finally b
            sorted_data = sortrows(acqTable, [2,3,4,1]);
            idx         = uint16(sorted_data(:,end));

            % sort b,te,Delta,delta
            this.b      = this.b(idx);
            this.te     = this.te(idx);
            this.Delta  = this.Delta(idx);
            this.delta  = this.delta(idx);   % bug fix: was previously reassigning this.Delta twice, leaving this.delta unsorted
            dwi         = dwi(:,:,:,idx);

            % --- Step 0: global-scalar reference-signal normalisation ---
            % Bring the WHOLE dataset onto an O(1) reference-signal scale
            % via ONE scalar for the entire dataset (as opposed to the
            % PER-VOXEL normalisation below, which the forward model's own
            % unit convention requires and which this step does NOT
            % replace). Unlike per-voxel normalisation, a single global
            % scalar preserves relative brightness BETWEEN voxels, which
            % the background-voxel check below needs -- checking a
            % per-voxel-normalised b=0 value (identically 1 by
            % construction) can never detect a near-zero-signal voxel.
            %
            % Single-echo (or several b=0 shells at the same TE): the
            % reference is just the (mean, if >1) b=0 signal itself.
            % Multi-echo: the b=0 shells are ALREADY T2/T2*-decayed by
            % their own TE, so the reference is instead the b=0 signal
            % EXTRAPOLATED back to TE=0 via a per-voxel log-linear fit
            % across the b=0 shells' TEs (see local_S0_TE0_lsq).
            Nshells    = numel(this.b);
            dwi_Sl0_g  = dwi(:,:,:,1:Nshells);   % Sl0 block, pre-per-voxel-normalisation
            b0idx      = find(this.b(1:Nshells) < 1e-6);
            if isempty(b0idx)
                error('GACELLE:noB0shell', 'No b=0 shell found in this.b; cannot compute a reference signal.');
            end
            te0 = this.te(b0idx);

            if numel(unique(te0)) <= 1
                % single-echo (or several b=0 replicates at one TE)
                S0map = mean(dwi_Sl0_g(:,:,:,b0idx), 4);
            else
                % multi-echo: extrapolate to TE=0
                [~,S0map] = this.local_S0_TE0_lsq(dwi_Sl0_g(:,:,:,b0idx), te0, mask);
            end

            scaleFactor = median(S0map(mask>0), 'omitmissing');
            if ~isfinite(scaleFactor) || scaleFactor <= 0
                error('GACELLE:badScaleFactor', ...
                    'Computed global reference signal is non-positive/non-finite (%.4g) -- check input data/mask.', scaleFactor);
            end
            dwi = dwi ./ scaleFactor;

            % background check uses the GLOBALLY- (not yet per-voxel-)
            % normalised b=0 signal, captured before it is corrupted to
            % an unconditional 1 by the per-voxel step below
            dwi_Sl0_bg = dwi(:,:,:,1:Nshells);

            % normalised by the first volume (isFitS0 not supported by
            % this class -- always runs)
            dwi = dwi ./ dwi(:,:,:,1);

            % --- Step 2: exclude biophysically impossible signal ---
            dwi_Sl0         = dwi(:,:,:,1:Nshells);          % Sl0 block
            dwi_Sl0_rn      = dwi_Sl0 ./ dwi_Sl0(:,:,:,1);   % per-voxel-normalised
            mask_impossible = any(abs(dwi_Sl0_rn) > 1 + this.thres_impossible, 4);
            mask_valid      = ~mask_impossible;

            % --- Step 3: exclude near-zero signal (background voxels) ---
            mask_background = dwi_Sl0_bg(:,:,:,1) < this.thres_bkg;  % first shell = lowest b
            mask_valid      = mask_valid & ~mask_background;

            % --- Step 4: exclude incoherent signal (random noise pattern) ---
            dwi_2D         = utils.reshape_ND2GD(dwi_Sl0_rn, mask_valid);
            if size(dwi_2D, 2) > 0
                signalTemplate = median(dwi_2D, 2,'omitmissing');           % median across voxels
                signalTemplate = (signalTemplate - mean(signalTemplate,'omitmissing')) ./ ...
                                  std(signalTemplate,'omitmissing');

                Rcorr = zeros(1, size(dwi_2D,2));
                for k = 1:size(dwi_2D,2)
                    signalVoxel = dwi_2D(:,k);
                    denom       = std(signalVoxel);
                    if denom < eps
                        Rcorr(k) = 0;   % flat signal -> zero correlation
                    else
                        signalVoxel = (signalVoxel - mean(signalVoxel)) ./ denom;
                        Rcorr(k)    = corr(signalTemplate, signalVoxel);
                    end
                end

                Rcorr           = utils.reshape_GD2ND(Rcorr, mask_valid);
                mask_incoherent = Rcorr < this.thres_similarity;
                mask_valid      = mask_valid & ~mask_incoherent;
            end

            % --- Step 5: remove NaN/Inf ---
            [dwi,mask_naninf] = utils.remove_img_naninf(dwi,mask);
            mask_naninf        = max(mask_naninf, [], 4);
            mask_valid         = mask_valid & mask_naninf;

            % --- Report and update mask ---
            Nexcluded = sum(mask(:)) - sum(mask_valid(:));
            if Nexcluded > 0
                fprintf('Signal mask updated: %d voxels excluded (%.1f%% of original mask).\n', ...
                    Nexcluded, 100*Nexcluded/sum(mask(:)));
                fprintf('  NaN/Inf        : %d\n', sum(mask_naninf(:) & mask(:)));
                fprintf('  Impossible     : %d\n', sum(mask_impossible(:) & mask(:)));
                fprintf('  Background     : %d\n', sum(mask_background(:) & mask(:)));
                fprintf('  Incoherent     : %d\n', sum(mask_incoherent(:) & mask(:)));
                disp('Please use the updated mask in subsequent analysis.');
                mask = mask_valid;
            end

        end

        % compute weights for optimisation
        function w = compute_optimisation_weights(this,mask,lossFunction,lmax)
        % 
        % Output
        % ------
        % w         : N-D signal masked wegiths
        %
            dims = size(mask,1:3);

            % lmax dependent weights
            l = 0:2:lmax;
            w = zeros([dims numel(this.b)*numel(l)],'single');
            for kl = 1:(lmax/2+1)
                for kb = 1:numel(this.b)
                    w(:,:,:,(kl-1)*numel(this.b)+kb) = 1/ (2*l(kl)+1);
                end
            end
            % if L1 then take square root
            if strcmpi(lossFunction,'l1')
                w = sqrt(w);
            end
            w = w ./ max(w(:));
            
        end

        %%%%% Prior estimation related functions %%%%%

        % determine how the starting points will be set up
        function x0 = determine_x0(this,y,mask,fitting) 

            disp('---------------');
            disp('Starting points');
            disp('---------------');

            dims = size(mask,1:3);

            if ischar(fitting.start)
                switch lower(fitting.start)
                    case 'likelihood'
                        % using maximum likelihood method to estimate starting points
                        x0 = this.estimate_prior(y,mask,[]);
                        % R2a and k2a are global constants
                        if any(ismember(this.modelParams,'R2a')); x0.R2a = this.R2c;    end
                        if any(ismember(this.modelParams,'k2a')); x0.k2a = this.rho2;   end
    
                    case 'default'
                        % use fixed points
                        fprintf('Using default starting points for all voxels at [%s]: [%s]\n', cell2str(this.modelParams),replace(num2str(this.startPoint(:).',' %.2f'),' ',','));
                        x0 = utils.initialise_x0(dims,this.modelParams,this.startPoint);
                        % R2a and k2a are global constants
                        if any(ismember(this.modelParams,'R2a')); x0.R2a = this.R2c;    end
                        if any(ismember(this.modelParams,'k2a')); x0.k2a = this.rho2;   end

                end
            elseif isstruct(fitting.start)
                % PER-PARAMETER, OPTIONALLY PER-VOXEL user-defined
                % starting point, addressed by NAME: fitting.start.(name)
                % (e.g. fitting.start = struct('r', r0), an MDN-seeded
                % start) -- ported from gpuMEAxCaliberSMT.m's
                % determine_x0. May be a scalar (broadcast to every
                % voxel) or a full array matching mask's spatial size.
                % Any model parameter NOT named here falls back to this
                % model's own DEFAULT starting value.
                x0 = utils.initialise_x0(dims,this.modelParams,this.startPoint);
                userFields = fieldnames(fitting.start);
                appliedFields = {};
                for kf = 1:numel(userFields)
                    pname = userFields{kf};
                    if ~any(strcmp(this.modelParams,pname))
                        continue   % not an active parameter for this call -- ignore rather than error
                    end
                    v = fitting.start.(pname);
                    if isscalar(v)
                        x0.(pname) = ones(dims,'single') * v;
                    else
                        if ~isequal(size(v,1:3),dims)
                            error('fitting.start.%s must be scalar or match mask''s spatial size [%s]; got [%s].', ...
                                pname, num2str(dims), num2str(size(v,1:3)));
                        end
                        x0.(pname) = single(v);
                    end
                    appliedFields{end+1} = pname; %#ok<AGROW>
                end
                fprintf('Using default starting points for [%s], with per-parameter overrides for [%s]\n', ...
                    cell2str(this.modelParams), cell2str(appliedFields));
                % R2a and k2a are global constants
                if any(ismember(this.modelParams,'R2a')); x0.R2a = this.R2c;    end
                if any(ismember(this.modelParams,'k2a')); x0.k2a = this.rho2;   end
            else
                % user defined starting point
                x0 = fitting.start(:);
                fprintf('Using user-defined starting points for all voxels at [%s]: [%s]\n',cell2str(this.modelParams),replace(num2str(x0(:).',' %.2f'),' ',','));
                x0 = utils.initialise_x0(dims,this.modelParams,x0);
                if any(ismember(this.modelParams,'R2a')); x0.R2a = this.R2c;    end
                if any(ismember(this.modelParams,'k2a')); x0.k2a = this.rho2;   end

            end

            % make sure the input is bounded
            x0 = askadam.set_boundary(x0,fitting.ub,fitting.lb);
            
            fprintf('Estimation lower bound [%s]: [%s]\n',      cell2str(this.modelParams),replace(num2str(fitting.lb(:).',' %.2f'),' ',','));
            fprintf('Estimation upper bound [%s]: [%s]\n',      cell2str(this.modelParams),replace(num2str(fitting.ub(:).',' %.2f'),'  ',','));
            ('---------------');
        end

        % using maximum likelihood method to estimate starting points
        function pars0 = estimate_prior(this,dwi,mask, Nsample)
        % Estimation starting points for NEXI using likehood method

            start = tic;
            
            disp('Estimate starting points based on likelihood ...')

            % manage pool
            pool            = gcp('nocreate');
            isDeletepool    = false;
            if numel(mask(mask>0)) > 1e4    % only start a pool if many voxels
                if isempty(pool)
                    Nworker = min(max(8,floor(maxNumCompThreads/4)),maxNumCompThreads);
                    pool    = parpool('Processes',Nworker);
                    isDeletepool = true;
                end
            end

            if nargin < 4 || isempty(Nsample)
                Nsample = 1e4;
            end
            % create training data
            [x_train, S_train] = this.traindata(Nsample);

            % reshape input data,  put DWI dimension to 1st dim
            dims    = size(dwi);
            dwi     = permute(dwi,[4 1 2 3]);
            dwi     = reshape(dwi,[dims(4), prod(dims(1:3))]);

            % find masked voxels
            ind     = find(mask(:));

            Nparam = numel(this.modelParams) ;

            pars0_mask  = zeros(Nparam,length(ind),'single');
            if ~isempty(pool)
                parfor kvol = 1:length(ind)
                    pars0_mask(:,kvol) = this.likelihood(dwi(:,ind(kvol)), x_train, S_train);
                end
            else
                for kvol = 1:length(ind)
                    pars0_mask(:,kvol) = this.likelihood(dwi(:,ind(kvol)), x_train, S_train);
                end
            end
            pars           = zeros(Nparam,size(dwi,2),'single');
            pars(:,ind)    = pars0_mask;

            % reshape estimation into image
            pars           = permute(reshape(pars,[size(pars,1) dims(1:3)]),[2 3 4 1]);

            ET  = duration(0,0,toc(start),'Format','hh:mm:ss');
            fprintf('Starting points estimated. Elapsed time (hh:mm:ss): %s \n',string(ET));
            if isDeletepool
                delete(pool);
            end

            for km = 1:size(pars,4)
                pars0.(this.modelParams{km}) = pars(:,:,:,km); ...
            end
            % global constant for the data
            if any(ismember(this.modelParams,'R2a'))
                pars0.R2a  = unique(pars0.R2a);
            end
            if any(ismember(this.modelParams,'k2a'))
                pars0.k2a  = unique(pars0.k2a);
            end

        end

        % generate training data for likelihood
        function [x_train, S_train, intervals] = traindata(this, N_samples, varargin)

            if nargin < 3
                intervals = [ 0.01 0.9  ;   % neurite fraction
                                 0 0.8  ;   % fcsf
                               0.5 1    ;   % DeR
                               0.1 5    ;   % axon radius, um;   
                               0.1 0.1  ;   % radius CoV
                                20 50   ;   % R2e
                         this.rho2 this.rho2   % k2a 
                          this.R2c this.R2c];  % R2a
            else
                intervals = varargin{1};
            end

            numBSample  = numel(gather(this.b));
            numParam    = numel(this.modelParams);
            % batch size can be modified according to available hardware
            batch_size  = 1e3;
            reps        = ceil(N_samples/batch_size);
            x_train     = zeros(numParam,batch_size,reps,'single');
            S_train     = zeros(numBSample,batch_size,reps,'single');
            for k = 1:reps
                % generate random parameter guesses and construct batch for NN signal evaluation
                pars = intervals(:,1) + diff(intervals,[],2).*rand(size(intervals,1),batch_size);

                idx = [];

                % minimal fitting parameters
                params.f    = pars(1,:);
                params.DeR  = pars(3,:);
                params.r    = pars(4,:);
                params.r_cov= pars(5,:);

                % check other parameters
                if any(ismember(this.modelParams,'fcsf'))
                    params.fcsf = pars(2,:);
                else
                    idx = cat(1,idx,2);
                end
                if any(ismember(this.modelParams,'R2e'))
                    params.R2e  = pars(6,:);
                else
                    idx = cat(1,idx,6);
                end
                if any(ismember(this.modelParams,'R2a'))
                    params.R2a  = pars(7,:);
                else
                    idx = cat(1,idx,7);
                end
                if any(ismember(this.modelParams,'k2a'))
                    params.k2a  = pars(8,:);
                else
                    idx = cat(1,idx,8);
                end
                % remove non fitting parameters
                pars(idx,:) = [];

                S = this.FWD(params);

                % remaining signals (dot, soma)
                x_train(:,:,k) = pars;
                S_train(:,:,k) = S;

            end

        end
        
        % likelihood
        function [pars_best, sse_best] = likelihood(this, S0, x_train, S_train)
            
            lmax = 0;
            wt = kron(ones(size(this.b)), 1./(2*(0:2:lmax)+1));
            wt = wt(:);
            nL = floor(lmax/2);
            S0 = S0(1:numel(this.b)*(nL+1),:);
            % batch size can be modified according to available hardware
            [Nx, ~, reps] = size(x_train);
            [~, Nv] = size(S0);
            pars_best = zeros(Nx,Nv);
            sse_best  = inf(1, Nv);
            for k = 1:reps
                pars = x_train(:,:,k);
                S    = S_train(:,:,k);
                for i = 1:Nv
                    S0i = S0(:,i);

                    % scale generated signals (fit S0) to input signal
                    sse = sum(wt.*(S0i - (S0i'*S)./dot(S,S).*S).^2);

                    % store best encountered parameter combination
                    [sse_new,best_index] = min(sse);
                    if sse_new<sse_best(i)
                        sse_best(i)    = sse_new;
                        pars_best(:,i) = pars(:,best_index);
                    end
                end
            end

        end
    
        %%  Signal related functions
        
        % Forward model
        function s = FWD(this, pars)

            % minimal fitting parameters
            f   = pars.f;
            DeR = pars.DeR;
            r   = pars.r;
            r_cov = pars.r_cov;
            % extra fitting parameters
            if isfield(pars,'fcsf')
                fcsf = pars.fcsf;
            else
                fcsf = 0;
            end
            if isfield(pars,'R2e')
                R2e = pars.R2e;
            else
                R2e = 0;
            end
            if isfield(pars,'R2a')
                R2a = pars.R2a;
            else
                R2a = this.R2c;
            end
            if isfield(pars,'k2a')
                k2a = pars.k2a;
            else
                k2a = this.rho2;
            end

            % compute theoretical effective radius for each contrast, for
            % whichever distribution family this object is configured for
            [reff_AxCaliber, reff_T2] = this.moments_to_effective_radii(r, r_cov, this.distribution);

            % intra-axonal signal
            Sa = this.diffusion_relaxation_SMT_stick(this.g, this.delta, this.Delta, this.b,this.te,this.D0,reff_AxCaliber,reff_T2,this.Da, R2a, k2a, this.model) ;
            % extracellular signal
            Se = this.diffusion_relaxation_SMT_zeppelin(this.b,this.te,this.DeL,DeR, R2e);
            % Combined signal
            s = (1-fcsf).*(f.*Sa + (1-f).*Se) + fcsf.*this.Scsf;

            % normalised to 1st echo, b=0
            s = s ./ s(1,:,:,:,:);
                
            % make sure s cannot be greater than 1
            s = min(s,1);
                
        end

    end

    methods(Static)

        %% Utility

        % Voxelwise closed-form mono-exponential decay fit, used ONLY to
        % extrapolate the b=0 signal back to TE=0 for prepare_dwi_data's
        % global-scalar reference-signal step. Ported verbatim from
        % gpuMEAxCaliberSMT.m's local_S0_TE0_lsq (self-contained, no
        % cross-class dependency).
        %
        % Input
        % -----------
        % img       : 4D multi-echo magnitude image, [x,y,z,te]
        % te        : 1D echo times, same length as img's 4th dimension
        % mask      : 3D signal mask, [x,y,z]
        %
        % Output
        % -----------
        % r2        : 3D R2 map [1/te's time unit], masked
        % m0        : 3D extrapolated S0 (signal at te=0) map, masked
        function [r2,m0] = local_S0_TE0_lsq(img,te,mask)

            img = double(img);
            te  = double(te);

            % set range of R2 and T2
            minT2s      = min(te)/20;
            maxT2s      = max(te)*20;
            ranger2     = [1/maxT2s, 1/minT2s];

            [nx,ny,nz,nt] = size(img);

            x       = ones(nt,2);
            x(:,2)  = -te(:);
            y       = permute(log(abs(img)),[4 1 2 3]);

            y       = reshape(y,[size(y,1) numel(y)/size(y,1)]);
            b       = x\y;
            r2      = reshape( b(2,:),nx,ny,nz) .* mask;
            m0      = exp(reshape( b(1,:),nx,ny,nz)) .* mask;

            r2(r2>max(ranger2)) = max(ranger2);
            r2(r2<min(ranger2)) = min(ranger2);

            m0(m0<0) = 0;

        end

        function [k,theta] = gamma_mean_cov_to_shape_scale(mu,cov)
            % k: shape
            % theta: scale
            cov     = max(cov,1e-8); % avoid cov=0
            k       = 1 ./ cov.^2;
            theta   = mu.*cov.^2;

        end

        % Converts (mean radius mu, coefficient of variation cov) of a
        % radius distribution into the two effective radii the forward
        % model needs: reff_T2 (for the k2a/r T2 term) and reff_AxCaliber
        % (for the diffusion-restriction term), for whichever
        % distribution family is requested.
        %
        % reff_T2 = E[r^2]/E[r] = mu*(1+cov^2) is IDENTICAL for all four
        % families (verified symbolically -- gamma, lognormal and inverse
        % Gaussian all reduce to exactly this closed form; log-logistic
        % is this by definition) -- no per-family branching needed there.
        %
        % reff_AxCaliber = (E[r^6]/E[r^2])^(1/4) (the MR-effective-radius
        % convention of Veraart et al. 2020, eLife,
        % https://doi.org/10.7554/eLife.49855) IS family-specific:
        %   gamma:            mu*[(1+2c^2)(1+3c^2)(1+4c^2)(1+5c^2)]^(1/4)
        %                     (algebraically identical to this class's
        %                     original theta*[(k+2)(k+3)(k+4)(k+5)]^(1/4)
        %                     form via gamma_mean_cov_to_shape_scale)
        %   lognormal:        mu*(1+c^2)^3.5
        %   inverse Gaussian: mu*[(1+15c^2+105c^4+420c^6+945c^8+945c^10)/(1+c^2)]^(1/4)
        %                     (derived from the IG cumulant sequence
        %                     kappa_n = (2n-3)!! mu^n c^(2(n-1)), converted
        %                     to raw moments)
        %   log-logistic:     NO closed form -- the (mu,cov)->shape
        %                     mapping requires solving tan(phi)/phi=1+c^2
        %                     numerically, AND the 6th moment (hence
        %                     reff_AxCaliber) only exists for shape>6,
        %                     i.e. cov < loglogistic_cGrid's max
        %                     (~0.3204, the exact singularity at
        %                     tan(pi/6)/(pi/6)-1). Uses the precomputed
        %                     loglogistic_cGrid/loglogistic_reffOverMu
        %                     lookup table (see their definitions below)
        %                     via interp1, which is dlarray/dlgradient-
        %                     compatible (verified) so this stays
        %                     differentiable inside askadam. cov is
        %                     defensively clamped below the table's max
        %                     first, since askadam's box constraint
        %                     (this.ub for r_cov, tightened to 0.30 in
        %                     the constructor for this family) only
        %                     projects AFTER each gradient step, not
        %                     during it.
        %
        % All three closed forms reduce to reff = mu as cov -> 0 (the
        % single-point-radius limit), matching the original gamma-only
        % behaviour when the distribution collapses to a delta function.
        function [reff_AxCaliber, reff_T2] = moments_to_effective_radii(mu, cov, distribution)

            reff_T2 = mu .* (1 + cov.^2);   % universal -- see header comment

            switch lower(distribution)
                case 'gamma'
                    [k,theta]      = gpuMEAxCaliberSMT_radiusDist.gamma_mean_cov_to_shape_scale(mu,cov);
                    reff_AxCaliber = theta.*((k+2).*(k+3).*(k+4).*(k+5)).^(1/4);

                case 'lognormal'
                    reff_AxCaliber = mu .* (1+cov.^2).^3.5;

                case 'inversegaussian'
                    reff_AxCaliber = mu .* ((1 + 15*cov.^2 + 105*cov.^4 + 420*cov.^6 + 945*cov.^8 + 945*cov.^10) ./ (1+cov.^2)).^(1/4);

                case 'loglogistic'
                    % defensive clamp -- see header comment
                    covMax   = gpuMEAxCaliberSMT_radiusDist.loglogistic_cGrid(end);
                    covClamp = min(cov, covMax);
                    ratio    = interp1(gpuMEAxCaliberSMT_radiusDist.loglogistic_cGrid, gpuMEAxCaliberSMT_radiusDist.loglogistic_reffOverMu, covClamp);
                    reff_AxCaliber = mu .* ratio;

                otherwise
                    error('gpuMEAxCaliberSMT_radiusDist:unknownDistribution', ...
                        'Unknown distribution ''%s'' -- must be one of gamma|lognormal|inversegaussian|loglogistic.', distribution);
            end

        end


        %%%%%%%%%% Compartmental signal
        % restricted stick
        function S = diffusion_relaxation_SMT_stick(g, delta, Delta,b,te,D0,reff_diff,reff_T2,Da, R2a, k2a, model)

            switch lower(model)
                case 'narrow'
                    C = gpuMEAxCaliberSMT_radiusDist.neuman(g, delta, reff_diff, D0);
                case 'wide'
                    C = gpuMEAxCaliberSMT_radiusDist.widepulse_r(g, delta, Delta, reff_diff, D0);    % less memory efficient but faster
            end

            % clamp b.*Da - C away from <=0 -- the gamma-distribution's
            % effective diffusion radius (reff_diff) can grow larger than
            % any single-point r ever could (see gamma_mean_cov_to_shape_
            % scale's (k+2)(k+3)(k+4)(k+5) inflation factor), pushing C
            % past b.*Da during askadam's gradient descent and hitting a
            % GPU sqrt-of-negative-real domain error. exp(-C) itself needs
            % no clamp (just decays toward 0). Same defensive idiom
            % diffusion_relaxation_SMT_zeppelin below already uses for
            % dDe.
            bDaC = max(b.*Da - C, gpuMEAxCaliberSMT_radiusDist.epsilon);
            S = sqrt(pi./(4*bDaC)) .* exp(-C) .* erf(sqrt(bDaC)) .* exp(-te.*( R2a + k2a./reff_T2));

        end

        % zeppelin
        function S = diffusion_relaxation_SMT_zeppelin(b,te,Da,Dr,R2e)

            dDe = Da - Dr;              
            dDe = max(dDe, gpuMEAxCaliberSMT_radiusDist.epsilon);    % avoid division by zeros and negative values for sqrt

            S = sqrt(pi./(4.*b.*dDe)) .* exp(-b.*Dr) .* erf(sqrt(b *dDe)) .* exp(-te.*R2e);

        end
        
        % unrestricted sphere
        function S = diffusion_relaxation_SMT_sphere_unrestricted(b,te,D,R2)

            S = exp(-b.*D) .*exp(-te.*R2);

        end

        % unrestricted stick
        function S = diffusion_relaxation_SMT_stick_unrestricted(b,te,Da, R2a, k2a)

            S = sqrt(pi./(4*(b.*Da ))) .* erf(sqrt(b.*Da )) .* exp(-te.*( R2a + k2a./r));

        end

        %%%%%%%%%% size related signal
        % narrow pulse solution axon
        function s = neuman(g, delta, r, D0)

            s = (7/48)*g.^2.*delta*r.^4/D0;
        end

        function s = narrowpulse_sphere(g, delta, r, D0)
            s = (16/175)*g.^2.*delta*r^4/D0;
        end

        % wide pulse solution
        function s = widepulse_r(g, ldelta, BDELTA,r, D0)

            k           = 10;
            bm2_tmp     = gpuMEAxCaliberSMT_radiusDist.bm2(1:k); if isgpuarray(r); bm2_tmp = gpuArray(single(bm2_tmp)); end
            bm2_tmp     = permute(bm2_tmp(:),[2 3 1]);

            td          = r.^2./D0;
            bardelta    = ldelta./td ;
            barDelta    = BDELTA./td ;
            bm2bardelta = bm2_tmp.*bardelta;
            bm2barDelta = bm2_tmp.*barDelta;
            s = (2/(bm2_tmp.^3.*(bm2_tmp-1))).*(-2 ...
                        + 2*bm2bardelta ...
                        + 2*exp(-bm2bardelta) ...
                        + 2*exp(-bm2barDelta) ...
                        - exp(-bm2barDelta-bm2bardelta)...
                        - exp(-bm2barDelta+bm2bardelta));
            s = sum(s,3).*D0.*g.^2.*td.^3;
            
        end

        %%%%%%%%%%%%%%
        % check and set default fitting algorithm parameters
        function fitting2 = check_set_default(fitting)
            % get basic fitting setting check
            fitting2 = askadam.check_set_default_basic(fitting);

            % get customised fitting setting check
            if ~isfield(fitting,'regmap');      fitting2.regmap     = {'f'};            end
            if ~isfield(fitting,'start');       fitting2.start      = 'likelihood';     end
            if ~isfield(fitting,'isFitCSF');    fitting2.isFitCSF   = true;             end
            if ~isfield(fitting,'isFitR2a');    fitting2.isFitR2a   = false;            end
            if ~isfield(fitting,'isFitk2a');    fitting2.isFitk2a   = false;            end

            if ~iscell(fitting2.regmap)
                fitting2.regmap = cellstr(fitting2.regmap);
            end

        end
    
    end

end
